/**
 * CRUD operations for Metric View Proposals -- backed by Lakebase (Prisma).
 *
 * Metric views are first-class standalone artifacts: generated by the Genie
 * engine (Phase A) or a standalone API, stored independently, and referenced
 * by Genie spaces and dashboards via deployment validation.
 */

import { withPrisma } from "@/lib/prisma";
import type {
  MetricViewDefinition,
  MetricViewProposal,
} from "@/lib/metric-views/types";
import { proposalToDefinition } from "@/lib/metric-views/legacy-adapter";
import { parseMetricViewYaml } from "@/lib/metric-views/parser";
import { serializeMetricViewYaml } from "@/lib/metric-views/serializer";
import {
  compactValidationEvidence,
  evidenceSkipped,
  type ValidationEvidence,
} from "@/lib/validation/evidence";
import { logger } from "@/lib/logger";
import { isMetricViewValidationDeployable } from "@/lib/metric-views/deployability";
import {
  applyMetricViewImproveDiff,
  fingerprintMetricViewDefinition,
  parseMetricViewImproveDiff,
  type MetricViewImproveDiff,
} from "@/lib/metric-views/improve-diff";
import {
  promoteSemanticAssetManifest,
} from "@/lib/semantic-assets/manifest";
import { validateFqn } from "@/lib/validation";

// ---------------------------------------------------------------------------
// Public types
// ---------------------------------------------------------------------------

export interface StoredMetricViewProposal {
  id: string;
  runId: string | null;
  schemaScope: string;
  domain: string | null;
  subdomain: string | null;
  name: string;
  description: string | null;
  definition?: MetricViewDefinition;
  yaml: string;
  ddl: string;
  sourceTables: string[];
  hasJoins: boolean;
  classification: string | null;
  rationale: string | null;
  existingFqn: string | null;
  improveDiff: MetricViewImproveDiff | null;
  improveBaseDefinition?: MetricViewDefinition;
  validationStatus: string;
  validationIssues: string[];
  validatorVersion: string | null;
  validationEvidence: ValidationEvidence[];
  validatedAt: string | null;
  deploymentStatus: string;
  deployedFqn: string | null;
  deployedAt: string | null;
  ownerEmail: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface MetricViewAccessScope {
  ownerEmail: string;
  sharedIds: string[];
}

// ---------------------------------------------------------------------------
// Mappers
// ---------------------------------------------------------------------------

/**
 * Re-run persisted JSON through the canonical serializer/parser boundary.
 * This validates unknown JSON and returns the parser-normalized IR rather than
 * trusting a structural cast from JSON.parse.
 */
function parseStoredDefinition(
  definitionJson: string | null,
  proposal: Pick<MetricViewProposal, "name" | "yaml">,
): MetricViewDefinition | null {
  if (definitionJson === null) return proposalToDefinition(proposal);
  try {
    const unknownDefinition: unknown = JSON.parse(definitionJson);
    if (
      typeof unknownDefinition !== "object" ||
      unknownDefinition === null ||
      Array.isArray(unknownDefinition) ||
      typeof (unknownDefinition as { name?: unknown }).name !== "string"
    ) {
      throw new Error("Stored metric view definition has no valid name.");
    }
    const definitionName = (unknownDefinition as { name: string }).name;
    const canonicalYaml = serializeMetricViewYaml(
      unknownDefinition as MetricViewDefinition,
    );
    return parseMetricViewYaml(canonicalYaml, definitionName);
  } catch {
    return null;
  }
}

function serializeStoredDefinition(
  definition: MetricViewDefinition | null | undefined,
): string | null {
  if (!definition) return null;
  try {
    const canonicalYaml = serializeMetricViewYaml(definition);
    const normalized = parseMetricViewYaml(canonicalYaml, definition.name);
    return JSON.stringify(normalized);
  } catch {
    return null;
  }
}

const DEFINITION_INTEGRITY_ISSUE =
  "Typed metric view definition is unavailable or corrupt.";

type FailClosedStatus = Exclude<MetricViewProposal["validationStatus"], "valid">;

function failClosedValidation(
  issues: string[],
  evidence: ValidationEvidence[],
  code: string,
  message: string,
  validationStatus: FailClosedStatus = "unverified",
): {
  validationStatus: FailClosedStatus;
  validationIssues: string[];
  validatorVersion: null;
  validationEvidence: ValidationEvidence[];
  validatedAt: null;
} {
  return {
    validationStatus,
    validationIssues: [...new Set([...issues, message])],
    validatorVersion: null,
    validationEvidence: [
      ...evidence.filter(
        (entry) => entry.status !== "passed" && entry.code !== code,
      ),
      evidenceSkipped("metric_view_integrity", code, message),
    ],
    validatedAt: null,
  };
}

function normalizeProposalForPersistence(proposal: MetricViewProposal): {
  proposal: MetricViewProposal;
  definitionJson: string | null;
} {
  const definitionJson = serializeStoredDefinition(proposal.definition);
  if (
    proposal.validationStatus === "valid" &&
    (!definitionJson || !isMetricViewValidationDeployable(proposal))
  ) {
    const message = definitionJson
      ? "Valid metric view status requires complete Release 1 validation provenance."
      : DEFINITION_INTEGRITY_ISSUE;
    const failedClosed = failClosedValidation(
      proposal.validationIssues,
      proposal.validationEvidence ?? [],
      definitionJson
        ? "METRIC_VIEW_VALID_PROVENANCE_REQUIRED"
        : "METRIC_VIEW_DEFINITION_REQUIRED",
      message,
    );
    return {
      proposal: {
        ...proposal,
        validationStatus: failedClosed.validationStatus,
        validationIssues: failedClosed.validationIssues,
        validatorVersion: undefined,
        validationEvidence: failedClosed.validationEvidence,
        validatedAt: undefined,
      },
      definitionJson,
    };
  }
  return { proposal, definitionJson };
}

function dbRowToStored(row: {
  id: string;
  runId: string | null;
  schemaScope: string;
  domain: string | null;
  subdomain: string | null;
  name: string;
  description: string | null;
  definitionJson: string | null;
  yaml: string;
  ddl: string;
  sourceTablesJson: string | null;
  hasJoins: boolean;
  classification: string | null;
  rationale: string | null;
  existingFqn: string | null;
  improveDiffJson: string | null;
  improveBaseJson: string | null;
  validationStatus: string | null;
  validationIssues: string | null;
  validatorVersion: string | null;
  validationEvidenceJson: string | null;
  validatedAt: Date | null;
  deploymentStatus: string;
  deployedFqn: string | null;
  deployedAt: Date | null;
  ownerEmail: string | null;
  createdAt: Date;
  updatedAt: Date;
}): StoredMetricViewProposal {
  let sourceTables: string[] = [];
  try {
    sourceTables = row.sourceTablesJson ? JSON.parse(row.sourceTablesJson) : [];
  } catch {
    /* empty */
  }

  let validationIssues: string[] = [];
  try {
    validationIssues = row.validationIssues ? JSON.parse(row.validationIssues) : [];
  } catch {
    /* empty */
  }

  let validationEvidence: ValidationEvidence[] = [];
  try {
    validationEvidence = compactValidationEvidence(
      row.validationEvidenceJson
        ? (JSON.parse(row.validationEvidenceJson) as ValidationEvidence[])
        : [],
    );
  } catch {
    /* empty */
  }
  let improveDiff: MetricViewImproveDiff | null = null;
  try {
    improveDiff = row.improveDiffJson
      ? parseMetricViewImproveDiff(JSON.parse(row.improveDiffJson))
      : null;
  } catch {
    /* malformed legacy data fails closed at deployment because no diff is returned */
  }
  const improveBaseDefinition = row.improveBaseJson
    ? parseStoredDefinition(row.improveBaseJson, {
        name: row.name,
        yaml: "",
      })
    : null;

  const definition = parseStoredDefinition(row.definitionJson, {
    name: row.name,
    yaml: row.yaml,
  });
  let improvementBindingValid = true;
  if (row.classification === "improve") {
    try {
      if (
        !definition ||
        !improveDiff ||
        !improveBaseDefinition ||
        !row.existingFqn ||
        improveDiff.existingFqn.toLowerCase() !== row.existingFqn.toLowerCase()
      ) {
        throw new Error("missing binding");
      }
      const recomputed = applyMetricViewImproveDiff(improveBaseDefinition, improveDiff);
      if (
        fingerprintMetricViewDefinition(recomputed) !==
        fingerprintMetricViewDefinition(definition)
      ) {
        throw new Error("artifact drift");
      }
    } catch {
      improvementBindingValid = false;
      improveDiff = null;
    }
  }
  const mappedValidation = definition && improvementBindingValid
    ? {
        validationStatus: row.validationStatus ?? "pending",
        validationIssues,
        validatorVersion: row.validatorVersion,
        validationEvidence,
        validatedAt: row.validatedAt?.toISOString() ?? null,
      }
    : failClosedValidation(
        validationIssues,
        validationEvidence,
        "METRIC_VIEW_DEFINITION_UNAVAILABLE",
        improvementBindingValid
          ? DEFINITION_INTEGRITY_ISSUE
          : "Metric view improvement binding is unavailable, corrupt, or drifted.",
      );

  return {
    id: row.id,
    runId: row.runId,
    schemaScope: row.schemaScope,
    domain: row.domain,
    subdomain: row.subdomain,
    name: row.name,
    description: row.description,
    ...(definition ? { definition } : {}),
    yaml: row.yaml,
    ddl: row.ddl,
    sourceTables,
    hasJoins: row.hasJoins,
    classification: row.classification,
    rationale: row.rationale,
    existingFqn: row.existingFqn,
    improveDiff,
    ...(improvementBindingValid && improveBaseDefinition
      ? { improveBaseDefinition }
      : {}),
    ...mappedValidation,
    deploymentStatus: row.deploymentStatus,
    deployedFqn: row.deployedFqn,
    deployedAt: row.deployedAt?.toISOString() ?? null,
    ownerEmail: row.ownerEmail,
    createdAt: row.createdAt.toISOString(),
    updatedAt: row.updatedAt.toISOString(),
  };
}

// ---------------------------------------------------------------------------
// Write
// ---------------------------------------------------------------------------

/**
 * Persist metric view proposals for a run + domain. Replaces existing proposals
 * for the same run + domain combination.
 */
export async function saveMetricViewProposals(
  runId: string | null,
  schemaScope: string,
  domain: string | null,
  proposals: MetricViewProposal[],
  ownerEmail?: string | null,
): Promise<void> {
  if (proposals.length === 0) return;

  await withPrisma(async (prisma) => {
    await prisma.$transaction(
      async (tx: Parameters<Parameters<typeof prisma.$transaction>[0]>[0]) => {
        // Delete existing proposals for this run + domain
        if (runId && domain) {
          await tx.forgeMetricViewProposal.deleteMany({
            where: { runId, domain },
          });
        } else if (runId) {
          await tx.forgeMetricViewProposal.deleteMany({
            where: { runId, schemaScope },
          });
        }

        const slug = (s: string) =>
          s
            .toLowerCase()
            .replace(/[^a-z0-9]+/g, "_")
            .replace(/^_|_$/g, "");

        await tx.forgeMetricViewProposal.createMany({
          data: proposals.map((inputProposal, idx) => {
            const { proposal: p, definitionJson } =
              normalizeProposalForPersistence(inputProposal);
            return {
              id: runId
                ? `${runId}_mv_${slug(domain ?? schemaScope)}_${idx}`
                : `standalone_mv_${slug(schemaScope)}_${Date.now()}_${idx}`,
              runId,
              schemaScope,
              domain,
              subdomain: p.subdomain ?? null,
              name: p.name,
              description: p.description || null,
              definitionJson,
              yaml: p.yaml,
              ddl: p.ddl,
              sourceTablesJson: JSON.stringify(p.sourceTables),
              hasJoins: p.hasJoins,
              classification: p.classification ?? null,
              rationale: p.rationale ?? null,
              existingFqn: p.existingFqn ?? null,
              improveDiffJson: p.improveDiff ? JSON.stringify(p.improveDiff) : null,
              improveBaseJson: p.improveBaseDefinition
                ? serializeStoredDefinition(p.improveBaseDefinition)
                : null,
              validationStatus: p.validationStatus,
              validationIssues: JSON.stringify(p.validationIssues),
              validatorVersion: p.validatorVersion ?? null,
              validationEvidenceJson: p.validationEvidence
                ? JSON.stringify(compactValidationEvidence(p.validationEvidence))
                : null,
              validatedAt: p.validatedAt ? new Date(p.validatedAt) : null,
              deploymentStatus: "proposed",
              ownerEmail: ownerEmail ?? null,
            };
          }),
        });
      },
    );
  });

  logger.info("Metric view proposals saved", {
    runId,
    schemaScope,
    domain,
    count: proposals.length,
  });
}

// ---------------------------------------------------------------------------
// Read
// ---------------------------------------------------------------------------

/** All proposals for a pipeline run. */
export async function getMetricViewProposalsByRun(
  runId: string,
  access?: MetricViewAccessScope,
): Promise<StoredMetricViewProposal[]> {
  return withPrisma(async (prisma) => {
    const rows = await prisma.forgeMetricViewProposal.findMany({
      where: {
        runId,
        ...(access && {
          OR: [{ ownerEmail: access.ownerEmail }, { id: { in: access.sharedIds } }],
        }),
      },
      orderBy: { createdAt: "asc" },
    });
    return rows.map(dbRowToStored);
  });
}

/** All proposals for a specific run and domain. */
export async function getMetricViewProposalsByRunDomain(
  runId: string,
  domain: string,
  access?: MetricViewAccessScope,
): Promise<StoredMetricViewProposal[]> {
  return withPrisma(async (prisma) => {
    const rows = await prisma.forgeMetricViewProposal.findMany({
      where: {
        runId,
        domain,
        ...(access && {
          OR: [{ ownerEmail: access.ownerEmail }, { id: { in: access.sharedIds } }],
        }),
      },
      orderBy: { createdAt: "asc" },
    });
    return rows.map(dbRowToStored);
  });
}

/** All proposals for a schema scope (for standalone use). */
export async function getMetricViewProposalsBySchema(
  schemaScope: string,
  access?: MetricViewAccessScope,
): Promise<StoredMetricViewProposal[]> {
  return withPrisma(async (prisma) => {
    const rows = await prisma.forgeMetricViewProposal.findMany({
      where: {
        schemaScope,
        ...(access && {
          OR: [{ ownerEmail: access.ownerEmail }, { id: { in: access.sharedIds } }],
        }),
      },
      orderBy: { createdAt: "desc" },
    });
    return rows.map(dbRowToStored);
  });
}

/** Only deployed metric views for a schema scope. */
export async function getDeployedMetricViews(
  schemaScope: string,
): Promise<StoredMetricViewProposal[]> {
  return withPrisma(async (prisma) => {
    const rows = await prisma.forgeMetricViewProposal.findMany({
      where: { schemaScope, deploymentStatus: "deployed" },
      orderBy: { deployedAt: "desc" },
    });
    return rows.map(dbRowToStored);
  });
}

/** Single proposal by ID. */
export async function getMetricViewProposalById(
  id: string,
): Promise<StoredMetricViewProposal | null> {
  return withPrisma(async (prisma) => {
    const row = await prisma.forgeMetricViewProposal.findUnique({
      where: { id },
    });
    return row ? dbRowToStored(row) : null;
  });
}

// ---------------------------------------------------------------------------
// Update
// ---------------------------------------------------------------------------

/** Mark a proposal as deployed, failed, or back to proposed. */
export async function updateDeploymentStatus(
  id: string,
  status: "failed" | "proposed",
): Promise<void> {
  if ((status as string) === "deployed") {
    throw new Error(
      "Successful metric view deployments must use promoteMetricViewDeployment",
    );
  }
  await withPrisma(async (prisma) => {
    await prisma.forgeMetricViewProposal.update({
      where: { id },
      data: {
        deploymentStatus: status,
        deployedFqn: null,
        deployedAt: null,
      },
    });
  });

  logger.info("Metric view deployment status updated", { id, status });
}

function promoteManifestAsset(
  manifestJson: string,
  proposal: {
    id: string;
    name: string;
    description: string | null;
    definitionJson: string | null;
    yaml: string;
    ddl: string;
    sourceTablesJson: string | null;
    existingFqn: string | null;
  },
  deployedFqn: string,
): string {
  const manifest = JSON.parse(manifestJson) as import("@/lib/semantic-assets/types").SemanticAssetManifest;
  if (manifest.version !== "1" || !Array.isArray(manifest.metricViews)) {
    throw new Error("Persisted semantic manifest is missing or malformed");
  }
  const definition = parseStoredDefinition(proposal.definitionJson, {
    name: proposal.name,
    yaml: proposal.yaml,
  });
  if (!definition) {
    throw new Error("Metric view promotion requires a typed merged definition");
  }
  let sourceTables: string[] = [];
  try {
    sourceTables = proposal.sourceTablesJson
      ? (JSON.parse(proposal.sourceTablesJson) as string[])
      : [];
  } catch {
    throw new Error("Metric view promotion source tables are malformed");
  }
  return JSON.stringify(
    promoteSemanticAssetManifest({
      manifest,
      proposal: {
        name: proposal.name,
        description: proposal.description ?? "",
        definition,
        ddl: proposal.ddl,
        sourceTables,
        ...(proposal.existingFqn ? { existingFqn: proposal.existingFqn } : {}),
      },
      proposalId: proposal.id,
      deployedFqn,
    }),
  );
}

/**
 * Atomically marks a successfully-created metric view as deployed and promotes
 * its run/domain semantic manifest to the observed live FQN.
 */
export async function promoteMetricViewDeployment(
  id: string,
  deployedFqn: string,
): Promise<void> {
  const validatedFqn = validateFqn(deployedFqn, "deployed metric view");
  await withPrisma(async (prisma) => {
    await prisma.$transaction(async (tx) => {
      const proposal = await tx.forgeMetricViewProposal.findUnique({ where: { id } });
      if (!proposal) throw new Error(`Metric view proposal "${id}" was not found`);

      if (proposal.runId && proposal.domain) {
        const recommendation = await tx.forgeGenieRecommendation.findUnique({
          where: {
            runId_domain: {
              runId: proposal.runId,
              domain: proposal.domain,
            },
          },
        });
        if (!recommendation?.trustedFunctions) {
          throw new Error(
            `Persisted semantic manifest is missing for ${proposal.runId}/${proposal.domain}`,
          );
        }
        const promotedManifest = promoteManifestAsset(
          recommendation.trustedFunctions,
          proposal,
          validatedFqn,
        );
        await tx.forgeGenieRecommendation.update({
          where: {
            runId_domain: {
              runId: proposal.runId,
              domain: proposal.domain,
            },
          },
          data: { trustedFunctions: promotedManifest },
        });
      }

      await tx.forgeMetricViewProposal.update({
        where: { id },
        data: {
          deploymentStatus: "deployed",
          deployedFqn: validatedFqn,
          deployedAt: new Date(),
        },
      });
    });
  });
  logger.info("Metric view deployment and semantic manifest promoted", {
    id,
    deployedFqn: validatedFqn,
  });
}

/** Update the YAML and DDL of an existing proposal (e.g. after user edit). */
export async function updateMetricViewProposal(
  id: string,
  data: {
    definition?: MetricViewDefinition | null;
    yaml?: string;
    ddl?: string;
    validationStatus?: MetricViewProposal["validationStatus"];
    validationIssues?: string[];
    validatorVersion?: string | null;
    validationEvidence?: ValidationEvidence[] | null;
    validatedAt?: string | null;
  },
): Promise<void> {
  const definitionJson =
    data.definition === undefined ? undefined : serializeStoredDefinition(data.definition);
  const hasCanonicalDefinitionReplacement =
    data.definition !== undefined && data.definition !== null && Boolean(definitionJson);
  const hasAtomicValidReplacement =
    hasCanonicalDefinitionReplacement &&
    data.validationStatus === "valid" &&
    isMetricViewValidationDeployable({
      validationStatus: data.validationStatus,
      validatorVersion: data.validatorVersion,
      validatedAt: data.validatedAt,
      validationEvidence: data.validationEvidence,
    });
  const definitionMutationInvalidatesProvenance =
    hasCanonicalDefinitionReplacement && !hasAtomicValidReplacement;
  const mustFailClosed =
    (data.definition !== undefined && !definitionJson) ||
    (data.validationStatus === "valid" &&
      (!hasCanonicalDefinitionReplacement ||
        !isMetricViewValidationDeployable({
          validationStatus: data.validationStatus,
          validatorVersion: data.validatorVersion,
          validatedAt: data.validatedAt,
          validationEvidence: data.validationEvidence,
        })));
  const failedClosed = mustFailClosed
    ? failClosedValidation(
        data.validationIssues ?? [],
        data.validationEvidence ?? [],
        definitionJson
          ? "METRIC_VIEW_VALID_PROVENANCE_REQUIRED"
          : "METRIC_VIEW_DEFINITION_REQUIRED",
        definitionJson
          ? "Valid metric view status requires complete Release 1 validation provenance."
          : DEFINITION_INTEGRITY_ISSUE,
        data.validationStatus && data.validationStatus !== "valid"
          ? data.validationStatus
          : "unverified",
      )
    : null;

  await withPrisma(async (prisma) => {
    await prisma.forgeMetricViewProposal.update({
      where: { id },
      data: {
        ...(data.definition !== undefined && {
          definitionJson,
        }),
        ...(data.yaml !== undefined && { yaml: data.yaml }),
        ...(data.ddl !== undefined && { ddl: data.ddl }),
        ...((data.validationStatus !== undefined ||
          failedClosed ||
          definitionMutationInvalidatesProvenance) && {
          validationStatus: definitionMutationInvalidatesProvenance
            ? "unverified"
            : (failedClosed?.validationStatus ?? data.validationStatus),
        }),
        ...((data.validationIssues !== undefined || failedClosed) && {
          validationIssues: JSON.stringify(
            failedClosed?.validationIssues ?? data.validationIssues,
          ),
        }),
        ...((data.validatorVersion !== undefined ||
          failedClosed ||
          definitionMutationInvalidatesProvenance) && {
          validatorVersion:
            failedClosed || definitionMutationInvalidatesProvenance
              ? null
              : data.validatorVersion,
        }),
        ...((data.validationEvidence !== undefined ||
          failedClosed ||
          definitionMutationInvalidatesProvenance) && {
          validationEvidenceJson:
            definitionMutationInvalidatesProvenance
              ? null
              : failedClosed
              ? JSON.stringify(compactValidationEvidence(failedClosed.validationEvidence))
              : data.validationEvidence === null
              ? null
              : JSON.stringify(compactValidationEvidence(data.validationEvidence)),
        }),
        ...((data.validatedAt !== undefined ||
          failedClosed ||
          definitionMutationInvalidatesProvenance) && {
          validatedAt:
            failedClosed || definitionMutationInvalidatesProvenance
            ? null
            : data.validatedAt === null
              ? null
              : new Date(data.validatedAt!),
        }),
      },
    });
  });
}

// ---------------------------------------------------------------------------
// Delete
// ---------------------------------------------------------------------------

/** Delete a single proposal. */
export async function deleteMetricViewProposal(id: string): Promise<void> {
  await withPrisma(async (prisma) => {
    await prisma.forgeMetricViewProposal.delete({ where: { id } });
  });
}

// ---------------------------------------------------------------------------
// Dependency lookup
// ---------------------------------------------------------------------------

/**
 * Find proposals whose name or deployedFqn matches the requested FQNs.
 * Used by deployment dependency validation.
 */
export async function findMetricViewProposalsByFqn(
  fqns: string[],
  access: MetricViewAccessScope,
): Promise<StoredMetricViewProposal[]> {
  if (fqns.length === 0) return [];

  const names = fqns.map((fqn) => fqn.split(".").pop()?.toLowerCase() ?? fqn.toLowerCase());

  return withPrisma(async (prisma) => {
    const rows = await prisma.forgeMetricViewProposal.findMany({
      where: {
        AND: [
          {
            OR: [{ deployedFqn: { in: fqns } }, { name: { in: names } }],
          },
          {
            OR: [{ ownerEmail: access.ownerEmail }, { id: { in: access.sharedIds } }],
          },
        ],
      },
      orderBy: { createdAt: "desc" },
    });
    return rows.map(dbRowToStored);
  });
}
